SCENE w=480 h=480 fit=contain
DEFS {
    GL id=theme_row units=bbox x1=0 y1=0 x2=0 y2=1 stops=[[0,#3B3B45],[1,#32323A]]
}
# style {"f":{"role":"surface-panel"},"s":{"role":"border-strong"}}
C cx=240 cy=250 rx=140 ry=140 sw=4 f=#1D1D23 s=#8E8E9E
# style {"s":{"role":"border-strong"}}
L p=[100,250,120,250] sw=3 s=#8E8E9E
# style {"s":{"role":"border-strong"}}
L p=[240,110,240,130] sw=3 s=#8E8E9E
# style {"s":{"role":"border-strong"}}
L p=[360,250,380,250] sw=3 s=#8E8E9E
G a=[240,250] r==clamp($gauge_level,0,1)*180-90 v==gt($gauge_present,0) {
    # style {"s":{"role":"accent"}}
    L p=[240,250,240,120] sw=4 s=#FF772D
}
# style {"f":{"role":"accent"}}
C cx=240 cy=250 rx=8 ry=8 f=#FF772D
# widget text txt1 {"x":40,"y":233,"w":56,"h":33.6,"style":"unit","text":"0","align":"right","state":false,"keys":{}}
G id=txt1 {
    T x=40 y=233 w=56 h=33.6 text="{=0:%.0f}" size=24 font="Barlow Medium" f=#A6A6B4 sh=[[0,2,2,0,#00000099]] align=right valign=middle fit=ellipsis
}
# widget text txt2 {"x":212,"y":72,"w":56,"h":33.6,"style":"unit","text":"50","align":"center","state":false,"keys":{}}
G id=txt2 {
    T x=212 y=72 w=56 h=33.6 text="{=50:%.0f}" size=24 font="Barlow Medium" f=#A6A6B4 sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
# widget text txt3 {"x":384,"y":233,"w":56,"h":33.6,"style":"unit","text":"100","align":"left","state":false,"keys":{}}
G id=txt3 {
    T x=384 y=233 w=56 h=33.6 text="{=100:%.0f}" size=24 font="Barlow Medium" f=#A6A6B4 sh=[[0,2,2,0,#00000099]] valign=middle fit=ellipsis
}
# widget text txt4 {"x":150,"y":270,"w":180,"h":47.6,"style":"value-lg","text":"{$gauge_value:%.0f}","align":"center","state":false,"keys":{}}
G id=txt4 {
    T x=150 y=270 w=180 h=47.6 text="{$gauge_value:%.0f}" size=34 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
# widget text txt5 {"x":160,"y":322,"w":160,"h":33.6,"style":"unit","text":"Pressure kPa","align":"center","state":false,"keys":{}}
G id=txt5 {
    T x=160 y=322 w=160 h=33.6 text="Pressure kPa" size=24 font="Barlow Medium" f=#A6A6B4 sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
# widget button btn1 {"x":24,"y":400,"w":200,"h":54,"states":[{"label":"Devices","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=btn1 {
    R id=btn1_hit click=1 x=24 y=400 w=200 h=54
    R x=24.5 y=400.5 w=199 h=53 rx=5.5 f=@theme_row s=#5A5A69 sw=1 fo==1-0.25*down
    T x=42 y=400 w=164 h=54 text=DEVICES size=26 font="Barlow Condensed Bold" cspace=3.85 f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
G v==lt(ver,11118) {
    R x=0 y=0 w=480 h=58 f=#000000CC
    T x=14.4 y=0 w=451.2 h=58 text="Update ScriptedScreens Vector to 0.11.118 or newer" size=26 f=#FFCC00
}

SCENE w=480 h=480 fit=contain
DEFS {
    GL id=theme_brand units=bbox x1=0 y1=0 x2=0 y2=1 stops=[[0,#1D4F7F],[1,#0D3B6A]]
    GL id=theme_row units=bbox x1=0 y1=0 x2=0 y2=1 stops=[[0,#3B3B45],[1,#32323A]]
}
# widget header vbhdr {"x":24,"y":24,"w":432,"h":64,"title":"Devices","clock":false,"counts":false,"keys":{}}
G id=vbhdr {
    R x=25.5 y=25.5 w=429 h=61 rx=12.5 f=@theme_brand s=#FF772D sw=3
    T x=42 y=30 w=386 h=52 text=DEVICES size=36 font="Barlow Condensed Bold" cspace=4.17 f=#FFFFFF sh=[[0,2,2,0,#00000099]] valign=middle fit=ellipsis
}
# widget repeater vbdev {"x":24,"y":100,"w":432,"h":162,"max":3,"layout":"list","cols":2,"pitch":56,"item":"row","fmt":"","click":true,"keys":{}}
G id=vbdev {
    R x=24 y=100 w=432 h=162
    RP n=3 {
        G v==lt(i,$vbdev_n) {
            R id=vbdev_r click=1 x=24 y==100+i*56 w=432 h=50
            R x=24.5 y==100+i*56+0.5 w=431 h=49 rx=5.5 f=@theme_row s=#5A5A69 sw=1
            C v==1-eq($vbdev_st[i],1)-eq($vbdev_st[i],2)-eq($vbdev_st[i],3) cx=47 cy==100+i*56+25 rx=9 ry=9 f=#A6A6B4
            C v==eq($vbdev_st[i],1) cx=47 cy==100+i*56+25 rx=9 ry=9 f=#7FD970 sh=[[0,0,10,0,#7FD970]]
            C v==eq($vbdev_st[i],2) cx=47 cy==100+i*56+25 rx=9 ry=9 f=#F2B233 sh=[[0,0,10,0,#F2B233]]
            C v==eq($vbdev_st[i],3) cx=47 cy==100+i*56+25 rx=9 ry=9 f=#F7777A sh=[[0,0,10,0,#F7777A]]
            T x=66 y==100+i*56 w==lerp(236,376,clamp(and($vbdev_ready,eq($vbdev_hasv[i],0)),0,1)) h=50 text="$vbdev_name[i]" size=28 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] valign=middle fit=ellipsis missing=""
            T v==not(and($vbdev_ready,eq($vbdev_hasv[i],0))) x=312 y==100+i*56 w=130 h=50 text="{$vbdev_v[i]:%.1f}" size=34 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=right valign=middle
        }
    }
}
# widget text vbmsg {"x":24,"y":284,"w":432,"h":40,"style":"value","text":"$vbdev_msg","align":"left","state":false,"keys":{}}
G id=vbmsg {
    T x=24 y=284 w=432 h=40 text=$vbdev_msg size=28 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] valign=middle fit=ellipsis
}
# widget text vbpg {"x":172,"y":343,"w":136,"h":40,"style":"value","text":"$vbdev_pg","align":"center","state":false,"keys":{}}
G id=vbpg {
    T x=172 y=343 w=136 h=40 text=$vbdev_pg size=28 font="Barlow SemiBold" f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
# widget button vbprev {"x":24,"y":336,"w":136,"h":54,"states":[{"label":"PREV","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
G id=vbprev {
    R id=vbprev_hit click=1 x=24 y=336 w=136 h=54
    R x=24.5 y=336.5 w=135 h=53 rx=5.5 f=@theme_row s=#5A5A69 sw=1 fo==1-0.25*down
    T x=42 y=336 w=100 h=54 text=PREV size=26 font="Barlow Condensed Bold" cspace=3.85 f=#FFFFFF sh=[[0,2,2,0,#00000099]] align=center valign=middle fit=ellipsis
}
# widget button vbnext {"x":320,"y":336,"w":136,"h":54,"states":[{"label":"NEXT","variant":"secondary","key":0}],"canDisable":false,"canSelect":false,"keys":{}}
